fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, t);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 { host::display::state_set(1, t); }
    host::display::state_set(2, down);
    let el: i32 = t - host::display::state_get(1);
    let mut p: i32 = el * 256 / 1200;
    if p > 256 { p = 256; }
    host::display::clear(0x101010);
    let hw: i32 = 70;
    let hh: i32 = 90;
    let rem: i32 = 256 - p;
    let bw: i32 = hw * rem / 256;
    let ty: i32 = cy - hh * rem / 256;
    host::display::fill_triangle(cx - bw, ty, cx + bw, ty, cx, cy, 0xd8b060);
    let pw: i32 = hw * p / 256;
    let ph: i32 = hh * p / 256;
    host::display::fill_triangle(cx - pw, cy + hh, cx + pw, cy + hh, cx, cy + hh - ph, 0xd8b060);
    if p < 256 && (t & 1) == 0 {
        host::display::draw_line(cx, cy, cx, cy + hh - ph, 0xffd080);
    }
    host::display::draw_line(cx - hw, cy - hh, cx + hw, cy - hh, 0xc0c0c0);
    host::display::draw_line(cx - hw, cy + hh, cx + hw, cy + hh, 0xc0c0c0);
    host::display::draw_line(cx - hw, cy - hh, cx, cy, 0xc0c0c0);
    host::display::draw_line(cx + hw, cy - hh, cx, cy, 0xc0c0c0);
    host::display::draw_line(cx, cy, cx - hw, cy + hh, 0xc0c0c0);
    host::display::draw_line(cx, cy, cx + hw, cy + hh, 0xc0c0c0);
    if p == 256 {
        host::display::draw_string(cx - 52, cy + hh + 16, "TAP TO FLIP", 0xffffff, 1);
    }
    host::display::present();
}
